```javascript
/**
 * Creates a debounced async function with cancellation support
 * @param {Function} asyncFn - The async function to debounce
 * @param {number} delay - Delay in milliseconds
 * @returns {Object} Object with debounced function and cancel method
 */
function createDebouncedAsync(asyncFn, delay) {
  let timeoutId = null;
  let currentPromise = null;
  let abortController = null;
  let isCancelled = false;

  const debouncedFn = (...args) => {
    // Clear existing timeout
    if (timeoutId) {
      clearTimeout(timeoutId);
    }

    // Cancel previous pending request
    if (abortController) {
      abortController.abort();
      isCancelled = true;
    }

    // Reset cancellation flag
    isCancelled = false;

    return new Promise((resolve, reject) => {
      timeoutId = setTimeout(async () => {
        // Create new abort controller for this request
        abortController = new AbortController();
        const signal = abortController.signal;

        try {
          // Check if request was cancelled during timeout
          if (isCancelled) {
            reject(new Error('Request cancelled'));
            return;
          }

          // Execute the async function with abort signal
          const result = await asyncFn(...args, signal);

          // Check again after execution (in case cancelled during execution)
          if (isCancelled) {
            reject(new Error('Request cancelled'));
            return;
          }

          resolve(result);
        } catch (error) {
          // Don't reject if it's an abort error (handled by cancellation)
          if (error.name === 'AbortError') {
            reject(new Error('Request cancelled'));
          } else {
            reject(error);
          }
        } finally {
          // Cleanup
          timeoutId = null;
          abortController = null;
        }
      }, delay);
    });
  };

  // Cancel method to abort pending requests
  debouncedFn.cancel = () => {
    if (timeoutId) {
      clearTimeout(timeoutId);
      timeoutId = null;
    }

    if (abortController) {
      abortController.abort();
      abortController = null;
    }

    isCancelled = true;
  };

  return debouncedFn;
}

