use std::num::IntErrorKind;

/// Safely parses a string into an i32, handling overflow and invalid input.
/// Returns None if parsing fails or if the value overflows.
fn safe_parse_i32(s: &str) -> Option<i32> {
    // Handle empty string
    if s.is_empty() {
        return None;
    }

    // Handle sign
    let (bytes, negative) = match s.as_bytes() {
        [b'+', rest @ ..] => (rest, false),
        [b'-', rest @ ..] => (rest, true),
        _ => (s.as_bytes(), false),
    };

    // Handle empty after sign
    if bytes.is_empty() {
        return None;
    }

    let mut result: i32 = 0;

    for &byte in bytes {
        // Check if character is a digit
        if !byte.is_ascii_digit() {
            return None;
        }

        let digit = (byte - b'0') as i32;

        // Check for overflow before multiplication
        // For positive numbers: result * 10 + digit > i32::MAX
        // For negative numbers: result * 10 - digit < i32::MIN
        if negative {
            // Check for underflow (negative overflow)
            if result < (i32::MIN + digit) / 10 {
                return None; // Would underflow
            }
            result = result * 10 - digit;
        } else {
            // Check for overflow
            if result > (i32::MAX - digit) / 10 {
                return None; // Would overflow
            }
            result = result * 10 + digit;
        }
    }

    Some(result)
}

