function deepMerge(...objects) {
    // Store visited objects to handle circular references
    const visited = new WeakMap();

    function isObject(item) {
        return item && typeof item === 'object' && !Array.isArray(item);
    }

    function merge(target, source) {
        // Handle circular references
        if (visited.has(source)) {
            return visited.get(source);
        }

        // If source is not an object, return it directly
        if (!isObject(source) && !Array.isArray(source)) {
            return source;
        }

        // Handle arrays
        if (Array.isArray(source)) {
            if (!Array.isArray(target)) {
                target = [];
            }

            // Store reference before processing to handle circular references
            visited.set(source, target);

            // Merge array elements
            source.forEach((item, index) => {
                if (isObject(item) || Array.isArray(item)) {
                    target[index] = merge(target[index], item);
                } else {
                    target[index] = item;
                }
            });

            return target;
        }

        // Handle objects
        if (!isObject(target)) {
            target = {};
        }

        // Store reference before processing to handle circular references
        visited.set(source, target);

        // Merge all properties from source to target
        for (const key of Object.keys(source)) {
            const sourceValue = source[key];
            const targetValue = target[key];

            if (isObject(sourceValue) || Array.isArray(sourceValue)) {
                target[key] = merge(targetValue, sourceValue);
            } else {
                target[key] = sourceValue;
            }
        }

        return target;
    }

    // Start with first object or empty object
    const result = objects[0] ? merge({}, objects[0]) : {};

    // Merge remaining objects
    for (let i = 1; i < objects.length; i++) {
        if (objects[i] !== null && objects[i] !== undefined) {
            merge(result, objects[i]);
        }
    }

    return result;
}

