fn max_product_of_three(numbers_str: &str) -> Option<i64> {
    // Parse the string into a vector of integers
    let numbers: Vec<i64> = numbers_str
        .split_whitespace()
        .filter_map(|s| s.parse().ok())
        .collect();

    // Handle edge case: fewer than 3 numbers
    if numbers.len() < 3 {
        return None;
    }

    // Sort the numbers
    let mut sorted = numbers.clone();
    sorted.sort();

    let n = sorted.len();

    // The maximum product can be either:
    // 1. Product of three largest numbers (all positive or all negative)
    let product1 = sorted[n-1] * sorted[n-2] * sorted[n-3];

    // 2. Product of two smallest numbers (could be negative) and the largest number
    //    This handles cases like [-10, -10, 1, 2, 3] where (-10 * -10 * 3) > (3 * 2 * 1)
    let product2 = sorted[0] * sorted[1] * sorted[n-1];

    Some(product1.max(product2))
}

fn main() {
    // Test cases
    let test_cases = vec![
        "1 2 3",
        "1 2 3 4",
        "-10 -10 1 2 3",
        "-5 -4 -3 -2 -1",
        "0 1 2",
        "-1 -2 -3",
        "1 2",
        "",
        "5 3 2 1 -10 -10",
    ];

    for test in test_cases {
        match max_product_of_three(test) {
            Some(product) => println!("'{}' -> {}", test, product),
            None => println!("'{}' -> None (fewer than 3 numbers)", test),
        }
    }
}
