```go
package cache

import (
    "sync"
    "time"
)

// Item represents a cache item with its value and expiration time
type Item struct {
    value      interface{}
    expiration int64 // Unix timestamp in nanoseconds
}

// Cache is a thread-safe in-memory cache with TTL expiration
type Cache struct {
    items map[string]*Item
    mu    sync.RWMutex
    stop  chan struct{}
}

// NewCache creates a new cache instance and starts the cleanup goroutine
func NewCache(cleanupInterval time.Duration) *Cache {
    c := &Cache{
        items: make(map[string]*Item),
        stop:  make(chan struct{}),
    }

    // Start cleanup goroutine if cleanup interval is provided
    if cleanupInterval > 0 {
        go c.cleanupLoop(cleanupInterval)
    }

    return c
}

// Set adds or updates a cache item with a TTL
func (c *Cache) Set(key string, value interface{}, ttl time.Duration) {
    c.mu.Lock()
    defer c.mu.Unlock()

    var expiration int64
    if ttl > 0 {
        expiration = time.Now().Add(ttl).UnixNano()
    }

    c.items[key] = &Item{
        value:      value,
        expiration: expiration,
    }
}

// Get retrieves a value from the cache
// Returns the value and a boolean indicating if the key was found and not expired
func (c *Cache) Get(key string) (interface{}, bool) {
    c.mu.RLock()
    item, found := c.items[key]
    c.mu.RUnlock()

    if !found {
        return nil, false
    }

    // Check if item has expired
    if item.expiration > 0 && time.Now().UnixNano() > item.expiration {
        // Item expired, delete it
        c.mu.Lock()
        delete(c.items, key)
        c.mu.Unlock()
        return nil, false
    }

    return item.value, true
}

// Delete removes a key from the cache
func (c *Cache) Delete(key string) {
    c.mu.Lock()
    defer c.mu.Unlock()
    delete(c.items, key)
}

