fn safe_parse_i32_detailed(s: &str) -> Result<i32, ParseError> {
    // Handle empty string
    if s.is_empty() {
        return Err(ParseError::EmptyInput);
    }

    // Handle sign
    let (bytes, negative) = match s.as_bytes() {
        [b'+', rest @ ..] => (rest, false),
        [b'-', rest @ ..] => (rest, true),
        _ => (s.as_bytes(), false),
    };

    // Handle empty after sign
    if bytes.is_empty() {
        return Err(ParseError::EmptyInput);
    }

    let mut result: i32 = 0;

    for (i, &byte) in bytes.iter().enumerate() {
        // Check if character is a digit
        if !byte.is_ascii_digit() {
            return Err(ParseError::InvalidCharacter(byte as char, i));
        }

        let digit = (byte - b'0') as i32;

        if negative {
            // Check for underflow (negative overflow)
            if result < (i32::MIN + digit) / 10 {
                return Err(ParseError::Underflow);
            }
            result = result * 10 - digit;
        } else {
            // Check for overflow
            if result > (i32::MAX - digit) / 10 {
                return Err(ParseError::Overflow);
            }
            result = result * 10 + digit;
        }
    }

    // Check for negative zero
    if negative && result == 0 {
        return Err(ParseError::NegativeZero);
    }

    Ok(result)
}

