// This is useful for cache-aside pattern and prevents thundering herd problem
func (c *Cache) GetOrSet(key string, ttl time.Duration, fn func() (interface{}, error)) (interface{}, error) {
    // First try to get without locking
    if value, found := c.Get(key); found {
        return value, nil
    }

    // Key not found or expired, need to set it
    c.mu.Lock()
    defer c.mu.Unlock()

    // Double-check after acquiring the write lock
    // This prevents the thundering herd problem
    if item, found := c.items[key]; found {
        if item.expiration == 0 || time.Now().UnixNano() < item.expiration {
            return item.value, nil
        }
    }

    // Execute the function to get the value
    value, err := fn()
    if err != nil {
        return nil, err
    }

    // Store in cache
    c.items[key] = &Item{
        value:      value,
        expiration: getExpirationTime(ttl),
    }

    return value, nil
